using System;
using System.IO;
using System.Runtime.Serialization;
using System.Security.Claims;
using System.Collections.Generic;
using System.Xml;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;

namespace DocumentService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentController : ControllerBase
    {
        private readonly IDocumentStore _store;
        private readonly ISerializationProvider _serializer;

        public DocumentController(IDocumentStore store, ISerializationProvider serializer)
        {
            _store = store;
            _serializer = serializer;
        }

        [HttpPost("upload")]
        [Authorize(Roles = "User,Admin")]
        public IActionResult UploadDocument([FromForm] DocumentUploadRequest request)
        {
            var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
            if (string.IsNullOrEmpty(userId))
                return Unauthorized();

            var metadata = _serializer.DeserializeMetadata(request.MetadataPayload, request.Format);
            if (metadata == null)
                return BadRequest("Invalid metadata");

            // Enforce ownership: user can only upload to their own namespace
            metadata.OwnerId = userId;
            metadata.UploadedAt = DateTime.UtcNow;

            _store.Save(metadata, request.FileContent);
            return Ok(new { id = metadata.DocumentId });
        }

        [HttpPost("admin/bulk-import")]
        [Authorize(Roles = "Admin")]
        public IActionResult BulkImport([FromForm] BulkImportRequest request)
        {
            var results = new List<string>();
            foreach (var entry in request.Entries)
            {
                var metadata = _serializer.DeserializeMetadata(entry.MetadataPayload, entry.Format);
                if (metadata != null)
                {
                    _store.Save(metadata, entry.FileContent);
                    results.Add(metadata.DocumentId);
                }
            }
            return Ok(new { imported = results });
        }
    }

    public interface ISerializationProvider
    {
        DocumentMetadata DeserializeMetadata(byte[] payload, string format);
    }

    public class SerializationProvider : ISerializationProvider
    {
        private static readonly HashSet<string> AllowedTypes = new HashSet<string>
        {
            typeof(DocumentMetadata).FullName,
            typeof(DocumentPermissions).FullName,
            typeof(string).FullName,
            typeof(DateTime).FullName,
            typeof(int).FullName
        };

        public DocumentMetadata DeserializeMetadata(byte[] payload, string format)
        {
            if (payload == null || payload.Length == 0)
                return null;

            switch (format?.ToLowerInvariant())
            {
                case "xml":
                    return DeserializeXml(payload);
                case "datacontract":
                    return DeserializeDataContract(payload);
                default:
                    return DeserializeXml(payload);
            }
        }

        private DocumentMetadata DeserializeXml(byte[] payload)
        {
            var serializer = new System.Xml.Serialization.XmlSerializer(typeof(DocumentMetadata));
            var readerSettings = new XmlReaderSettings
            {
                // Prevent XXE: disable DTD processing and external resolution
                DtdProcessing = DtdProcessing.Prohibit,
                XmlResolver = null,
                MaxCharactersFromEntities = 0
            };
            using (var stream = new MemoryStream(payload))
            using (var reader = XmlReader.Create(stream, readerSettings))
            {
                return (DocumentMetadata)serializer.Deserialize(reader);
            }
        }

        private DocumentMetadata DeserializeDataContract(byte[] payload)
        {
            var settings = new DataContractSerializerSettings
            {
                MaxItemsInObjectGraph = 1000,
                DataContractResolver = new SafeTypeResolver(AllowedTypes)
            };
            var serializer = new DataContractSerializer(typeof(DocumentMetadata), settings);
            using (var stream = new MemoryStream(payload))
            using (var reader = XmlDictionaryReader.CreateTextReader(stream, XmlDictionaryReaderQuotas.Max))
            {
                return (DocumentMetadata)serializer.ReadObject(reader, verifyObjectName: false);
            }
        }
    }

    public class SafeTypeResolver : DataContractResolver
    {
        private readonly HashSet<string> _allowedTypes;

        public SafeTypeResolver(HashSet<string> allowedTypes)
        {
            _allowedTypes = allowedTypes;
        }

        public override bool TryResolveType(Type type, Type declaredType, DataContractResolver knownTypeResolver,
            out XmlDictionaryString typeName, out XmlDictionaryString typeNamespace)
        {
            return knownTypeResolver.TryResolveType(type, declaredType, null, out typeName, out typeNamespace);
        }

        public override Type ResolveName(string typeName, string typeNamespace, Type declaredType,
            DataContractResolver knownTypeResolver)
        {
            var resolved = knownTypeResolver.ResolveName(typeName, typeNamespace, declaredType, null);
            if (resolved != null && _allowedTypes.Contains(resolved.FullName))
                return resolved;
            return null;
        }
    }

    [DataContract]
    public class DocumentMetadata
    {
        [DataMember] public string DocumentId { get; set; } = Guid.NewGuid().ToString();
        [DataMember] public string OwnerId { get; set; }
        [DataMember] public string Title { get; set; }
        [DataMember] public DateTime UploadedAt { get; set; }
        [DataMember] public DocumentPermissions Permissions { get; set; }
    }

    [DataContract]
    public class DocumentPermissions
    {
        [DataMember] public string AccessLevel { get; set; } = "private";
        [DataMember] public List<string> SharedWith { get; set; } = new List<string>();
        [DataMember] public string EffectiveRole { get; set; } = "User";
    }

    public class DocumentUploadRequest
    {
        public byte[] MetadataPayload { get; set; }
        public string Format { get; set; }
        public byte[] FileContent { get; set; }
    }

    public class BulkImportRequest
    {
        public List<BulkImportEntry> Entries { get; set; }
    }

    public class BulkImportEntry
    {
        public byte[] MetadataPayload { get; set; }
        public string Format { get; set; }
        public byte[] FileContent { get; set; }
    }

    public interface IDocumentStore
    {
        void Save(DocumentMetadata metadata, byte[] content);
        DocumentMetadata GetById(string id);
    }
}
